package fx_wormhole

type ImageRgb565 struct {
	Width  int32
	Height int32
	Data   []uint16
}

func GetImage() *ImageRgb565 {
	img := &ImageRgb565{
		Width:  32,
		Height: 32,
		Data:   make([]uint16, 32*32),
	}

	for i := 0; i < len(ImageRawData); i += 2 {
		pixel := uint16(ImageRawData[i]) | (uint16(ImageRawData[i+1]) << 8)
		img.Data[i/2] = pixel
	}

	return img
}

